def check_config():
    out = []
    try:
        cfg = K.load_lit_config()
    except Exception as e:                                     # noqa: BLE001
        return [R("配置可解析", "error", str(e)[:200],
                  "修好 YAML 语法；**空白名单会让检索退化为全网关键词搜索**")]
    # 注意：以前这里打印 cfg['_config_backend'] —— 那个键**从未被任何代码设置过**，
    # 报告永远显示"后端=None"，是纯粹的噪声（本轮删除）。
    out.append(R("配置可解析", "ok", f"刊数={len(cfg.get('journals') or [])}"))

    js = cfg.get("journals") or []
    if not js:
        out.append(R("期刊白名单", "error", "为空",
                     "白名单是范围边界；为空时 lit_discover 会退化为纯关键词检索"))
    else:
        tiers = {}
        no_issn, dup = [], {}
        for j in js:
            t = str(j.get("tier") or "（缺）")
            tiers[t] = tiers.get(t, 0) + 1
            if not str(j.get("issn_l") or "").strip():
                no_issn.append(j.get("name") or "?")
            key = str(j.get("issn_l") or j.get("name") or "").lower()
            dup[key] = dup.get(key, 0) + 1
        known = set((cfg.get("tiers") or {}).keys())
        unknown = [t for t in tiers if t not in known and t != "（缺）"]
        out.append(R("tier 分布", "ok" if not unknown else "warn",
                     "  ".join(f"{k}={v}" for k, v in sorted(tiers.items())),
                     f"未知档位 {unknown}（将按 default_tier 处理）" if unknown else ""))
        out.append(R("刊缺 issn_l", "ok" if not no_issn else "warn",
                     f"{len(no_issn)} 刊" + (f"：{', '.join(no_issn[:4])}" if no_issn else ""),
                     "用 lit_journals.py --resolve-missing 补" if no_issn else ""))
        dups = [k for k, v in dup.items() if v > 1 and k]
        out.append(R("刊重复", "ok" if not dups else "warn", f"{len(dups)} 条",
                     str(dups[:4]) if dups else ""))

    # 去重源可解析性与实际贡献（2026-10-09 实测：某个源递归 0 个 PDF 却一直"在线"）
    srcs = cfg.get("dedup_sources") or []
    lines, bad, empty = [], [], []
    for s in srcs:
        sid, p, scope = s.get("id"), str(s.get("path") or ""), s.get("scope")
        if not p:
            continue
        ap = p if os.path.isabs(p) else os.path.join(K.VAULT, *p.replace("\\", "/").split("/"))
        if scope == "kb":
            n_pdf = _count(os.path.join(ap, "**", "*.pdf"))
            n_md = _count(os.path.join(ap, "**", "*.md"))
            lines.append(f"{sid}(kb): {n_pdf} pdf / {n_md} md")
            if n_pdf + n_md == 0:
                empty.append(sid)
        else:
            gone = not os.path.isdir(ap)
            n_pdf = 0 if gone else _count(os.path.join(ap, "**", "*.pdf"))
            lines.append(f"{sid}(pdfs): {'缺失' if gone else str(n_pdf) + ' pdf'}")
            if gone:
                bad.append(sid)
            elif n_pdf == 0:
                empty.append(sid)
    out.append(R("去重源", "error" if bad else ("warn" if empty else "ok"),
                 "；".join(lines) or "（未配置）",
                 ("不可用：" + ", ".join(bad) if bad else "")
                 + ("；**贡献 0 篇**：" + ", ".join(empty) if empty else "")))
    z = (cfg.get("zotero") or {}).get("data_dir") or ""
    if z:
        zp = z if os.path.isabs(z) else os.path.join(K.VAULT, *str(z).split("/"))
        okz = os.path.isfile(os.path.join(zp, "zotero.sqlite"))
        out.append(R("Zotero 数据目录", "ok" if okz else "warn",
                     f"{zp}（zotero.sqlite {'有' if okz else '无'}）",
                     "" if okz else "断链或路径写错时 Zotero 源会静默漏扫"))
    else:
        out.append(R("Zotero 数据目录", "info", "未配置（跳过）"))
    return out


# ---------------------------------------------------------------- 3. 去重对账

def dump_snapshot(data):
    p = snapshot_path()
    os.makedirs(os.path.dirname(p), exist_ok=True)
    tmp = p + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
    os.replace(tmp, p)          # 原子写：快照被读到一半会污染环比


def load_snapshot():
    p = snapshot_path()
    if not os.path.exists(p):
        return {}
    try:
        with open(p, encoding="utf-8") as f:
            return json.load(f)
    except Exception:                                          # noqa: BLE001
        return {}


def check_dedup(cfg=None):
    """三方 DOI 对账：本机目录 ∪ 库内已建卡清单 ∪ 卡片页。"""
    out = []
    cfg = cfg or K.load_lit_config()
    cat_p = cfg["paths"]["catalogue"]
    doi_p = cfg["paths"]["doi_index"]

    cat_dois, cat_titles, polluted, by_source = set(), 0, [], {}
    cat_n = 0
    if os.path.exists(cat_p):
        try:
            with open(cat_p, encoding="utf-8") as f:
                cat = json.load(f)
            papers = cat.get("papers") or []
            cat_n = len(papers)
            for e in papers:
                raw = e.get("doi") or ""
                d = K.norm_doi(raw)
                if raw and d != raw.strip().lower():
                    polluted.append(raw[:60])
                if d:
                    cat_dois.add(d)
                if not (e.get("title") or "").strip():
                    cat_titles += 1
                for lf in (e.get("local_files") or []):
                    sid = lf.get("source") or "?"
                    by_source[sid] = by_source.get(sid, 0) + 1
            degraded = cat.get("degraded") or []
        except Exception as e:                                 # noqa: BLE001
            degraded = []
            out.append(R("去重目录可读", "error", f"{cat_p}：{e}"))
    else:
        degraded = []
        out.append(R("去重目录", "warn", f"不存在：{cat_p}",
                     "跑 lit_catalogue.py 建立（否则跨 run 去重失效）"))

    if cat_n:
        out.append(R("去重目录规模", "ok", f"{cat_n} 条"
                     + (f"（来源贡献：{by_source}）" if by_source else "")))
        pct = cat_titles / max(1, cat_n)
        out.append(R("目录条目缺标题", "warn" if pct > 0.3 else "ok",
                     f"{cat_titles}/{cat_n}（{pct:.0%}）",
                     "缺标题的条目无法人工辨认，也无法按标题去重" if pct > 0.3 else ""))
        out.append(R("DOI 未归一（尾部粘连）", "warn" if polluted else "ok",
                     f"{len(polluted)} 条" + (f"：{polluted[:3]}" if polluted else ""),
                     "跑 lit_catalogue.py 重建即可修复（kb_lib.norm_doi 已能截断中文标点）"
                     if polluted else ""))
        if degraded:
            out.append(R("去重目录降级标记", "warn", f"本次缺失源：{degraded}"))

    kb_dois = set()
    if os.path.exists(doi_p):
        try:
            with open(doi_p, encoding="utf-8") as f:
                d = json.load(f)
            # kb_dois.py 实际写的是 {"by_doi": {doi: ...}, "by_title": {...}}，这里兼容多种形状
            raw_list = []
            if isinstance(d, dict):
                for key in ("by_doi", "dois", "items", "papers"):
                    v = d.get(key)
                    if isinstance(v, dict):
                        raw_list.extend(v.keys())
                    elif isinstance(v, list):
                        raw_list.extend(v)
            elif isinstance(d, list):
                raw_list = d
            for x in raw_list:
                v = K.norm_doi(x if isinstance(x, str) else (
                    x.get("doi") if isinstance(x, dict) else ""))
                if v:
                    kb_dois.add(v)
            cnt = d.get("count") if isinstance(d, dict) else None
            out.append(R("库内 DOI 清单", "ok",
                         f"{len(kb_dois)} 条（{doc_rel(doi_p)}）"
                         + (f"；文件自称 count={cnt}" if cnt is not None else "")))
        except Exception as e:                                 # noqa: BLE001
            out.append(R("库内 DOI 清单可读", "warn", f"{doi_p}：{e}"))
    else:
        out.append(R("库内 DOI 清单", "warn", f"不存在：{doi_p}",
                     "跑 kb_dois.py（lit_ingest --apply 会自动跑）"))

    # 卡片页 DOI（第三来源，用于发现"卡建了但清单没更新"）
    card_dois = set()
    src_dir = os.path.join(K.VAULT, "wiki", "sources")
    if os.path.isdir(src_dir):
        for fn in os.listdir(src_dir):
            if not fn.lower().endswith(".md"):
                continue
            try:
                fm, _ = K.split_frontmatter(K.read_text(os.path.join(src_dir, fn)))
            except OSError:
                continue
            v = K.norm_doi((K.parse_frontmatter(fm) or {}).get("doi"))
            if v:
                card_dois.add(v)
    if card_dois:
        only_card = card_dois - kb_dois
        out.append(R("卡片 DOI ⊂ 库内清单", "warn" if only_card else "ok",
                     f"卡片 {len(card_dois)} 条，其中 {len(only_card)} 条不在清单里",
                     "跑 kb_dois.py 重建清单，否则这批文献不会参与去重"
                     if only_card else ""))
    return out


def doc_rel(p):
    try:
        return os.path.relpath(p, K.VAULT).replace("\\", "/")
    except ValueError:
        return p


# ---------------------------------------------------------------- 4. 欠账

def check_backlog(cfg=None):
    out = []
    cfg = cfg or K.load_lit_config()
    pdf_dir = cfg["paths"]["pdf_dir"]
    text_dir = cfg["paths"]["text_dir"]
    n_pdf = _count(os.path.join(pdf_dir, "**", "*.pdf")) if os.path.isdir(pdf_dir) else 0
    # 🔴 2026-10-11：raw/text 已分 7 个分类子目录，全文计数必须递归（glob **）。
    n_txt = _count(os.path.join(text_dir, "**", "*.md")) if os.path.isdir(text_dir) else 0
    n_card = len([f for f in os.listdir(os.path.join(K.VAULT, "wiki", "sources"))
                  if f.lower().endswith(".md")])
    out.append(R("三段规模", "info",
                 f"PDF {n_pdf}　全文 {n_txt}　卡片 {n_card}"))

    inbox = os.path.join(pdf_dir, "Manual Download")
    if os.path.isdir(inbox):
        n_in = len([f for f in os.listdir(inbox) if f.lower().endswith(".pdf")])
        out.append(R("手动下载收件箱", "warn" if n_in else "ok",
                     f"{n_in} 个待收编（{doc_rel(inbox)}）",
                     "跑 lit_manual_import.py（先干跑）" if n_in else ""))
    quar = os.path.join(pdf_dir, "_unmatched")
    if os.path.isdir(quar):
        n_q = len([f for f in os.listdir(quar) if f.lower().endswith(".pdf")])
        out.append(R("未匹配隔离区", "info" if not n_q else "warn", f"{n_q} 个",
                     "需要人工确认（文件名对不上任何候选）" if n_q else ""))

    ledger_p = os.path.join(cfg["paths"]["catalogue"]).replace("local_lit_catalogue.json",
                                                               "extract_ledger.json")
    if os.path.exists(ledger_p):
        try:
            with open(ledger_p, encoding="utf-8") as f:
                led = json.load(f)
            pend = sum(1 for r in (led.get("pdf") or {}).values() if not r.get("ok"))
            out.append(R("提取台账", "warn" if pend else "ok",
                         f"待提取 {pend}（对账于 {led.get('reconciled_at') or '未记录'}）",
                         "python tools/lit_batch.py --pending 查看" if pend else ""))
        except Exception as e:                                 # noqa: BLE001
            out.append(R("提取台账可读", "warn", str(e)[:120]))
    else:
        out.append(R("提取台账", "warn", "尚未建立",
                     "python tools/lit_batch.py --reconcile（会读懂 PDF 首页 DOI）"))
    return out


# ---------------------------------------------------------------- 5. 索引新鲜度

def check_index(cfg=None):
    out = []
    cfg = cfg or K.load_lit_config()
    wiki_newest = 0.0
    for d in ("sources", "concepts", "entities", "topics", "outputs"):
        p = os.path.join(K.VAULT, "wiki", d)
        if os.path.isdir(p):
            for fn in os.listdir(p):
                if fn.lower().endswith(".md"):
                    wiki_newest = max(wiki_newest, os.path.getmtime(os.path.join(p, fn)))
    # 🔴 2026-10-10 修：kb_corpus.py 的产物是 `wiki/.index/corpus/{meta,bm25}.json + chunks.jsonl`，
    #    不是 `wiki/.index/corpus.json`。查错路径会**误报"语料索引不存在"**（实测 corpus 明明刚建好）。
    for rel, why in (("wiki/.index/meta.json", "BM25 检索索引（kb_build_index.py）"),
                     ("wiki/.index/dois.json", "去重 DOI 清单（kb_dois.py）"),
                     ("wiki/.index/corpus/meta.json", "全文分块索引（kb_corpus.py --build）")):
        p = os.path.join(K.VAULT, *rel.split("/"))
        name = "语料索引" if "corpus" in rel else os.path.basename(rel)
        if not os.path.exists(p):
            out.append(R(name, "warn", f"不存在（{rel}）", why))
            continue
        detail = ""
        if "corpus" in rel:
            try:
                with open(p, encoding="utf-8") as f:
                    cd = json.load(f)
                detail = (f"｜{cd.get('files')} 文件 / {cd.get('chunks')} 块"
                          f"（建于 {cd.get('built_at')}）")
            except Exception:                                  # noqa: BLE001
                pass
        stale = os.path.getmtime(p) < wiki_newest - 60
        out.append(R(name, "warn" if stale else "ok",
                     ("比最新卡片旧" if stale else "新鲜")
                     + f"（{datetime.datetime.fromtimestamp(os.path.getmtime(p)):%Y-%m-%d %H:%M}）"
                     + detail,
                     why + "：新入库的页不会进检索" if stale else ""))
    # 交给 kb.py --doctor（若存在）复核，避免两套判断漂移
    kbpy = os.path.join(HERE, "kb.py")
    if os.path.exists(kbpy):
        try:
            r = subprocess.run([sys.executable, kbpy, "--doctor"], cwd=K.VAULT,
                               capture_output=True, text=True, encoding="utf-8",
                               errors="replace", timeout=180)
            tail = [ln.strip() for ln in ((r.stdout or "") + (r.stderr or "")).splitlines()
                    if ln.strip()][-3:]
            out.append(R("kb.py --doctor", "ok" if r.returncode == 0 else "warn",
                         f"rc={r.returncode}；" + " / ".join(tail)[:200]))
        except Exception as e:                                 # noqa: BLE001
            out.append(R("kb.py --doctor", "info", f"未跑成：{str(e)[:100]}"))
    return out


# ---------------------------------------------------------------- 6. 运行时适配（DSH / Claude Code）

def _fm(path):
    try:
        fm, _ = K.split_frontmatter(K.read_text(path))
        return K.parse_frontmatter(fm) or {}
    except OSError:
        return {}


def _junction_target(path):
    """Windows junction/符号链接的目标（读不出来返回 ''）。"""
    try:
        if not os.path.islink(path):
            # junction 在 Python 里 islink() 为 False，用目录重解析点判定
            out = subprocess.run(["cmd", "/c", "dir", "/al", os.path.dirname(path)],
                                 capture_output=True, text=True, encoding="utf-8",
                                 errors="replace", timeout=30)
            for ln in (out.stdout or "").splitlines():
                if os.path.basename(path).lower() in ln.lower() and "<JUNCTION>" in ln.upper():
                    m = re.search(r"\[(.+?)\]", ln)
                    return m.group(1) if m else ""
            return ""
        return os.readlink(path)
    except Exception:                                          # noqa: BLE001
        return ""


def check_runtimes():
    out = []
    # 全局 skill（Claude Code 与 DSH 共用同一份内容）
    g = os.path.join(os.environ.get("CLAUDE_HOME") or os.path.expanduser("~/.claude"), "skills", "lit-watch", "SKILL.md")
    if os.path.exists(g):
        fm = _fm(g)
        ok = bool(fm.get("name")) and bool(fm.get("description"))
        out.append(R("全局 skill lit-watch", "ok" if ok else "error",
                     f"name={fm.get('name')} whenToUse={'有' if fm.get('whenToUse') else '无'}"
                     f" trigger={fm.get('trigger') or '无'}",
                     "" if ok else "frontmatter 缺 name/description，DSH 会跳过该 skill"))
    else:
        # 全局（机器级）技能缺失是**新机器的正常状态**，不是库的故障 ⇒ 报 info 而非 error，
        # 否则新用户一跑体检就见红，真故障被淹没。（本库已装该技能，走上面的 ok 分支，行为不变。）
        out.append(R("全局 skill lit-watch", "info",
                     f"未安装全局技能（可选）：{g}"))
    # DSH 侧入口（junction）
    dsh = os.environ.get("DSH_HOME") or ""
    if dsh:
        link = os.path.join(dsh, "skills", "lit-watch")
        tgt = _junction_target(link)
        alive = bool(tgt) and os.path.exists(tgt)
        out.append(R("DSH skills 入口", "ok" if alive else "error",
                     f"{link} → {tgt or '（不是链接/读不到）'}",
                     "" if alive else "DSH 看不到该 skill；请把 lit-watch 链接进全局 skills 目录"))
    else:
        out.append(R("DSH skills 入口", "info", "未设置 DSH_HOME，跳过"))
    # KB 项目技能：.dsh/skills（真源）↔ .claude/skills（junction）
    proj_dsh = os.path.join(K.VAULT, ".dsh", "skills")
    proj_claude = os.path.join(K.VAULT, ".claude", "skills")
    if os.path.isdir(proj_dsh):
        names = [d for d in os.listdir(proj_dsh) if os.path.isdir(os.path.join(proj_dsh, d))]
        broken, missing = [], []
        for n in names:
            link = os.path.join(proj_claude, n)
            if not os.path.exists(link):
                missing.append(n)
                continue
            t = _junction_target(link)
            if t and not os.path.exists(t):
                broken.append(n)
        lvl = "error" if broken else ("warn" if missing else "ok")
        out.append(R("KB 项目技能双入口", lvl,
                     f"{len(names)} 个技能；claude 侧缺 {len(missing)}，断链 {len(broken)}",
                     (f"缺：{missing[:4]}" if missing else "")
                     + (f" 断链：{broken[:4]}" if broken else "")))
        has_pipeline = "lit-pipeline" in names
        out.append(R("项目技能 lit-pipeline", "ok" if has_pipeline else "warn",
                     "存在" if has_pipeline else "缺失",
                     "文献流程的项目级入口" if not has_pipeline else ""))
    # Claude Code 斜杠命令（两个运行时都能用的入口）
    cmds = [os.path.join(K.VAULT, ".claude", "commands", "lit-watch.md"),
            os.path.join(os.path.expanduser("~/.claude"), "commands", "lit-watch.md")]
    have = [c for c in cmds if os.path.exists(c)]
    out.append(R("斜杠命令 /lit-watch", "ok" if have else "warn",
                 have[0] if have else "未创建（Claude Code 里只能靠自然语言触发）",
                 "创建后 Claude Code 可直接 /lit-watch" if not have else ""))
    return out


# ---------------------------------------------------------------- 7. 自动化任务

def _cron_failure_note(bad, today):
    """把失败行分成「今天的」与「历史记录」，返回 (级别, 说明文本)。

    ⚠️ 抽成纯函数是为了**可自检**：2026-10-10 首版把这段直接写在 `check_automation` 里，
    而 `--selftest` 覆盖不到那条分支 —— 结果 `--selftest` 报 PASS、真实运行却
    `AttributeError: module 'datetime' has no attribute 'now'` **直接崩**。
    「自检通过 ≠ 该路径被走到」正是本轮反复修的假自检形态
    （见 CLAUDE.md §校验器自检纪律 第 7 条「有字符串≠功能正常」）。
    """
    bad_days = sorted({m.group(1) for ln in bad
                       for m in [re.search(r"(20\d{2}-\d{2}-\d{2})", ln)] if m})
    fresh = [d for d in bad_days if d == today]
    if not bad:
        return "ok", ""
    if fresh:
        return "warn", f"；失败 {len(bad)} 条，含今天 {today}"
    span = f"（{bad_days[0]}…{bad_days[-1]}）" if bad_days else ""
    return "info", f"；失败 {len(bad)} 条，均为历史记录{span}"


def check_automation(cfg=None):
    out = []
    cfg = cfg or K.load_lit_config()
    daily_root = K.lit_runs_dir(cfg, "daily")
    runs_root = K.lit_runs_dir(cfg, "runs")
    # 日志可能在新根（本轮起）或旧根（迁移前的历史）：两个都看，但优先新根。
    cron_cands = [os.path.join(runs_root, "cron.log"),
                  os.path.join(daily_root, "cron.log"),
                  os.path.join(K.VAULT, *LEGACY_RUNS.split("/"), "daily", "cron.log")]
    cron_log = next((p for p in cron_cands if os.path.exists(p)), "")
    if cron_log:
        try:
            lines = [ln for ln in K.read_text(cron_log).splitlines() if ln.strip()]
        except OSError:
            lines = []
        tail = lines[-6:]
        # 🔴 失败条目要**带上是哪一天**。旧版只说"最近失败 1 条"，读的人会以为**今天**失败了
        #    ——2026-10-10 实测就是这样：当天 4/4 方向成功、退出码 0，而体检仍在报"最近失败 1 条"，
        #    那其实是迁移前留在日志里的历史记录（且它指向已迁走的旧产物路径）。
        #    「把历史当现状」正是本库反复踩的一类失真，故这里显式给出日期。
        bad = [ln for ln in lines[-40:] if "rc=" in ln or "[FAIL]" in ln]
        lvl, detail = _cron_failure_note(
            bad, datetime.datetime.now().strftime("%Y-%m-%d"))
        out.append(R("每日任务日志", lvl,
                     f"{len(lines)} 行（{os.path.relpath(cron_log, K.VAULT)}）" + detail,
                     " | ".join(tail[-2:])[:200]))
    else:
        out.append(R("每日任务日志", "info", "尚无 cron.log"))
    # 空日期目录：新根与旧根都查（旧根的空目录正是 2026-10-09 事故的痕迹）
    for label, daily in (("", daily_root),
                         ("（旧根）", os.path.join(K.VAULT, *LEGACY_RUNS.split("/"), "daily"))):
        if not os.path.isdir(daily):
            continue
        empties = [d for d in os.listdir(daily)
                   if re.fullmatch(r"\d{4}-\d{2}-\d{2}", d)
                   and not any(f.startswith("cand_") or f == "digest.md"
                               for f in os.listdir(os.path.join(daily, d)))]
        out.append(R(f"空的每日目录{label}", "warn" if empties else "ok",
                     f"{len(empties)} 天无任何产物" + (f"：{empties[:3]}" if empties else ""),
                     "通常意味着当天任务被中途杀掉（外部终止不会留 traceback）"
                     if empties else ""))
    try:
        r = subprocess.run(["schtasks", "/query", "/tn", "litwatch-daily"],
                           capture_output=True, text=True, encoding="utf-8",
                           errors="replace", timeout=30)
        ok = r.returncode == 0
        out.append(R("计划任务 litwatch-daily", "ok" if ok else "warn",
                     "已注册" if ok else "查不到（或本环境无法查询任务计划）",
                     "" if ok else (r.stderr or r.stdout or "")[:160]))
    except Exception as e:                                     # noqa: BLE001
        out.append(R("计划任务 litwatch-daily", "info", f"无法查询：{str(e)[:100]}"))
    return out


# ---------------------------------------------------------------- 8. 库内健康度

def check_kb_health(sample=40):
    out = []
    src = os.path.join(K.VAULT, "wiki", "sources")
    if not os.path.isdir(src):
        return [R("卡片健康度", "warn", "wiki/sources 不存在")]
    files = [f for f in os.listdir(src) if f.lower().endswith(".md")]
    bad_fm, pending, unverified = [], 0, 0
    step = max(1, len(files) // sample)
    for fn in files[::step][:sample]:
        try:
            txt = K.read_text(os.path.join(src, fn))
        except OSError:
            continue
        fmr, body = K.split_frontmatter(txt)
        fm = K.parse_frontmatter(fmr)
        if not fmr.strip():
            bad_fm.append(fn)
        if "## 待精读" in body and "- [ ]" in body:
            pending += 1
        if "待核" in str(fm.get("source_reliability") or ""):
            unverified += 1
    n = min(len(files), sample)
    out.append(R("卡片 frontmatter 可解析", "error" if bad_fm else "ok",
                 f"抽样 {n} 张，异常 {len(bad_fm)}" + (f"：{bad_fm[:3]}" if bad_fm else ""),
                 "元数据静默丢失是本库代价最高的失效" if bad_fm else ""))
    out.append(R("未精读卡片（抽样）", "info",
                 f"{pending}/{n} 仍带未清空的 `## 待精读`"))
    out.append(R("source_reliability=待核（抽样）", "info", f"{unverified}/{n}"))
    return out


# ---------------------------------------------------------------- 修复

def do_fix(cfg=None, quiet=False):
    cfg = cfg or K.load_lit_config()
    steps = [("lit_catalogue.py", [sys.executable, os.path.join(HERE, "lit_catalogue.py")]),
             ("kb_dois.py", [sys.executable, os.path.join(HERE, "kb_dois.py")])]
    print("\n=== --fix：重建去重目录与 DOI 清单（幂等，只读仓库不删文件）===")
    rc_all = 0
    for name, cmd in steps:
        if not os.path.exists(cmd[1]):
            print(f"  [skip] {name} 不存在")
            continue
        env = dict(os.environ, PYTHONIOENCODING="utf-8")
        r = subprocess.run(cmd, cwd=K.VAULT, env=env, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=1800)
        tail = [ln.strip() for ln in ((r.stdout or "") + (r.stderr or "")).splitlines()
                if ln.strip()][-2:]
        print(f"  [{'ok  ' if r.returncode == 0 else 'warn'}] {name} rc={r.returncode}"
              + (f"：{' / '.join(tail)[:180]}" if tail else ""))
        rc_all = rc_all or r.returncode
    return rc_all


# ---------------------------------------------------------------- 渲染

def run_all():
    cfg = None
    try:
        cfg = K.load_lit_config()
    except Exception:                                          # noqa: BLE001
        pass
    checks = []
    checks += check_env()
    checks += check_layout()
    checks += check_config()
    checks += check_dedup(cfg)
    checks += check_backlog(cfg)
    checks += check_index(cfg)
    checks += check_runtimes()
    checks += check_automation(cfg)
    checks += check_kb_health()
    errors = [c for c in checks if c["level"] == "error"]
    warns = [c for c in checks if c["level"] == "warn"]
    return checks, errors, warns


def render(checks, quiet=False):
    icons = {"ok": "✅", "info": "·", "warn": "⚠️", "error": "❌"}
    for c in checks:
        if quiet and c["level"] in ("ok", "info"):
            continue
        print(f"{icons[c['level']]} {c['name']}: {c['detail']}")
        if c.get("hint") and c["level"] in ("warn", "error"):
            print(f"     → {c['hint']}")


def selftest():
    print("=== lit_doctor --selftest ===")
    ok = fail = 0

    def chk(name, cond, extra=""):
        nonlocal ok, fail
        if cond:
            print(f"  [ok  ] {name}")
            ok += 1
        else:
            print(f"  [FAIL] {name} {extra}")
            fail += 1

    import shutil
    import tempfile
    # ⚠️ 临时目录不得落在库根（旧版写 <cwd>/_litwatch-selftest-doctor，
    #    从库根执行时会在知识库里留垃圾，也会被 kb_toolcheck 判成"意外写盘"）。
    tmp = ""
    for base in (tempfile.gettempdir(), os.getcwd(), HERE):
        cand = os.path.join(base, "_litwatch-selftest-doctor")
        try:
            shutil.rmtree(cand, ignore_errors=True)
            os.makedirs(cand, exist_ok=True)
            with open(os.path.join(cand, ".probe"), "w", encoding="utf-8") as f:
                f.write("x")
            os.remove(os.path.join(cand, ".probe"))
            tmp = cand
            break
        except OSError:
            continue
    if not tmp:
        print("  [FAIL] 无法创建自检临时目录")
        return 1
    for d in ("wiki/sources", "raw/pdf", "raw/text",
              "raw/notes/lit-watch/state", "raw/notes/lit-watch/downloads"):
        os.makedirs(os.path.join(tmp, *d.split("/")), exist_ok=True)
    # 造一份"有毛病的库"：白名单为空 + 目录里 DOI 污染 + 缺标题 + 收件箱有货
    with open(os.path.join(tmp, "tools_lit_config.yaml"), "w", encoding="utf-8") as f:
        f.write("journals: []\ntiers:\n  T0: {relevance_min: 0.4, ingest_depth: enhanced}\n"
                "default_tier: T0\npaths:\n"
                "  runs_dir: raw/notes/lit-watch\n"
                "  download_dir: raw/notes/lit-watch/downloads\n"
                "  catalogue: raw/notes/lit-watch/state/local_lit_catalogue.json\n"
                "  doi_index: wiki/.index/dois.json\n"
                "  pdf_dir: raw/pdf\n  text_dir: raw/text\n")
    cat = {"papers": [
        {"doi": "10.1021/acsnano.5c20611）", "title": "", "local_files": [{"source": "kb_raw"}]},
        {"doi": "10.1002/adma.202500941。", "title": "T", "local_files": [{"source": "zotero"}]},
    ], "degraded": ["nihfe"]}
    cat_p = os.path.join(tmp, "raw/notes/lit-watch/state/local_lit_catalogue.json")
    with open(cat_p, "w", encoding="utf-8") as f:
        json.dump(cat, f, ensure_ascii=False)
    os.makedirs(os.path.join(tmp, "raw/pdf/Manual Download"), exist_ok=True)
    with open(os.path.join(tmp, "raw/pdf/Manual Download/x.pdf"), "wb") as f:
        f.write(b"%PDF-1.4 test")
    with open(os.path.join(tmp, "wiki/sources/2026-x-JACS.md"), "w",
              encoding="utf-8", newline="\n") as f:
        f.write('---\ncreated: 2026-10-09\ntype: source\ndoi: 10.1/ok\n'
                'source_reliability: "待核"\n---\n## 待精读\n- [ ] 读原文\n')

    cfgp, vault, wiki = K.LIT_CONFIG_PATH, K.VAULT, K.WIKI
    try:
        K.VAULT, K.WIKI = tmp, os.path.join(tmp, "wiki")
        K.LIT_CONFIG_PATH = os.path.join(tmp, "tools_lit_config.yaml")
        cfg = K.load_lit_config(K.LIT_CONFIG_PATH)
        cfg["paths"]["catalogue"] = cat_p
        cfg["paths"]["doi_index"] = os.path.join(tmp, "wiki/.index/dois.json")
        cfg["paths"]["pdf_dir"] = os.path.join(tmp, "raw/pdf")
        cfg["paths"]["text_dir"] = os.path.join(tmp, "raw/text")

        # 迁移纪律：快照必须落在临时库**内部**、且不在 _archive/ 下
        chk("体检快照落在 runs_dir/runs/ 且不落 _archive/",
            snapshot_path().startswith(tmp)
            and "_archive" not in snapshot_path().replace("\\", "/"))
        chk("script_dirs() 由配置派生且不含已解散的 raw/_park",
            not any("_park" in r for r, _why, _req in script_dirs())
            and any(r == "raw/notes/lit-watch" for r, _why, _req in script_dirs()))
        chk("产物目录缺失只报 info（不制造假警报）",
            all(req is True for r, _why, req in script_dirs()
                if r in ("wiki/sources", "raw/pdf", "raw/text"))
            and any(req is False for r, _why, req in script_dirs()
                    if r.endswith("lit-watch")))

        dedup = check_dedup(cfg)
        names = {c["name"]: c for c in dedup}
        chk("对账发现 DOI 未归一（尾部粘连）",
            any("DOI 未归一" in k and v["level"] == "warn" for k, v in names.items()),
            str(list(names)))
        chk("对账发现条目缺标题",
            any("缺标题" in k and v["level"] == "warn" for k, v in names.items()))
        chk("对账报出去重目录降级标记",
            any("降级" in k for k in names))
        chk("对账要求重建 DOI 清单（不存在）",
            any("DOI 清单" in k and v["level"] == "warn" for k, v in names.items()))

        bl = check_backlog(cfg)
        chk("欠账发现手动下载收件箱有货",
            any("收件箱" in c["name"] and c["level"] == "warn" for c in bl), str(bl[:2]))
        chk("欠账提示建立提取台账",
            any("台账" in c["name"] for c in bl))

        cc = check_config_synthetic(tmp, cfg)
        chk("配置体检发现白名单为空（error 级）",
            any("白名单" in c["name"] and c["level"] == "error" for c in cc),
            str([(c["name"], c["level"]) for c in cc]))

        kh = check_kb_health()
        chk("卡片健康度能读到待精读/待核",
            any("frontmatter" in c["name"] for c in kh), str(kh[:2]))

        # 🆕 2026-10-10 回归夹具：cron 失败条目的「今天 vs 历史」判定。
        #    这段逻辑首版写在 check_automation 里、**自检覆盖不到** ⇒ `--selftest` 报 PASS
        #    而真实运行 AttributeError 直接崩（正是 CLAUDE.md §校验器自检纪律 的形态）。
        #    抽成纯函数后就地反算，不再依赖"跑一次真的才知道"。
        _today = "2026-10-10"
        chk("cron 无失败行 → ok / 无附加说明",
            _cron_failure_note([], _today) == ("ok", ""))
        chk("cron 今天有失败 → warn（应当盖过体检结论）",
            _cron_failure_note([f"{_today} 07:47 rc=3"], _today)[0] == "warn")
        chk("cron 只有历史失败 → info（不得说成『最近失败』）",
            _cron_failure_note(["2026-10-09 07:47 rc=3221225786"], _today)[0] == "info")
        _lvl, _det = _cron_failure_note(["2026-10-09 07:47 rc=3221225786"], _today)
        chk("cron 历史失败的说明里必须带出日期",
            "2026-10-09" in _det and "历史" in _det, _det)
        chk("cron 今天与历史混合 → warn 且点名今天",
            _cron_failure_note(
                ["2026-10-09 rc=1", f"{_today} rc=3"], _today)[0] == "warn")
    finally:
        K.LIT_CONFIG_PATH, K.VAULT, K.WIKI = cfgp, vault, wiki
        shutil.rmtree(tmp, ignore_errors=True)

    print(f"\n{'SELFTEST PASSED' if fail == 0 else 'SELFTEST FAILED'}: {ok}/{ok + fail}")
    return 0 if fail == 0 else 1


def check_config_synthetic(tmp, cfg):
    """在临时库里跑 check_config 的等价断言（避免真的去读生产配置）。"""
    out = []
    js = cfg.get("journals") or []
    if not js:
        out.append(R("期刊白名单", "error", "为空", "白名单是范围边界"))
    for s in (cfg.get("dedup_sources") or []):
        p = str(s.get("path") or "")
        if p and not os.path.isdir(p if os.path.isabs(p)
                                  else os.path.join(tmp, *p.split("/"))):
            out.append(R("去重源", "error", f"{s.get('id')} 不可用"))
    return out


def main():
    ap = argparse.ArgumentParser(description="文献流水线体检与对账（只读；--fix 可安全重建去重数据）")
    ap.add_argument("--json", action="store_true", help="机器可读输出（并写快照）")
    ap.add_argument("--quiet", action="store_true", help="只打印有问题的项")
    ap.add_argument("--fix", action="store_true", help="重建去重目录与 DOI 清单（幂等）")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    checks, errors, warns = run_all()
    prev = load_snapshot()
    if args.json:
        payload = {"at": datetime.datetime.now().isoformat(timespec="seconds"),
                   "vault": K.VAULT, "checks": checks,
                   "errors": len(errors), "warnings": len(warns)}
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        try:
            dump_snapshot(payload)
        except OSError as e:
            print(f"[warn] 快照写不进去：{e}", file=sys.stderr)
    else:
        print(f"=== lit_doctor · {K.VAULT}")
        print(f"    {datetime.datetime.now():%Y-%m-%d %H:%M}　"
              f"检查 {len(checks)} 项：❌ {len(errors)}　⚠️ {len(warns)}　"
              f"✅ {len(checks) - len(errors) - len(warns)}\n")
        render(checks, quiet=args.quiet)
        if prev.get("errors") is not None:
            print(f"\n上次体检（{prev.get('at')}）：❌ {prev.get('errors')}　"
                  f"⚠️ {prev.get('warnings')}")
    if args.fix:
        do_fix()
    return 2 if errors else (1 if warns else 0)


if __name__ == "__main__":
    sys.exit(main())
